1	package consensus
2	
3	import (
4		"bytes"
5		"fmt"
6		"testing"
7	)
8	
9	// assertTxMatches 校验查询返回的交易与提交时的原交易逐字段一致：
10	// 发送者、序号、内容、费用、到期轮次、签名相同，标识对应，签名仍有效。
11	func assertTxMatches(t *testing.T, got, want *Transaction) {
12		t.Helper()
13		if got == nil {
14			t.Fatal("query returned nil transaction")
15		}
16		if !bytes.Equal(got.Sender, want.Sender) ||
17			got.Sequence != want.Sequence ||
18			!bytes.Equal(got.Content, want.Content) ||
19			got.Fee != want.Fee ||
20			got.Expiry != want.Expiry ||
21			!bytes.Equal(got.Signature, want.Signature) {
22			t.Fatalf("tx = {sender:%x seq:%d content:%q fee:%d expiry:%d sig:%x}, want {sender:%x seq:%d content:%q fee:%d expiry:%d sig:%x}",
23				got.Sender, got.Sequence, got.Content, got.Fee, got.Expiry, got.Signature,
24				want.Sender, want.Sequence, want.Content, want.Fee, want.Expiry, want.Signature)
25		}
26		if got.ID() != want.ID() {
27			t.Fatalf("tx id = %s, want %s", got.ID(), want.ID())
28		}
29		if !got.Verify() {
30			t.Fatal("stored transaction signature no longer verifies")
31		}
32	}
33	
34	// tamperQueryTx 以调用方身份尽力改写手中查询结果里的交易：
35	// 发送者公钥、内容、签名、费用、序号、到期轮次全部改写。
36	func tamperQueryTx(tx *Transaction) {
37		tx.Sender[0] ^= 0xff
38		tx.Content = append(tx.Content, "tampered"...)
39		tx.Signature[0] ^= 0xff
40		tx.Fee += 1000
41		tx.Sequence += 100
42		tx.Expiry = 1 // 改为当前轮次，试图让交易立即到期
43	}
44	
45	// 按标识查询与账户待处理查询返回的都是独立副本：调用方改写发送者公钥、内容、
46	// 签名、费用、序号、到期轮次后，节点再次查询仍返回提交时接收的完整交易，
47	// 原标识与内容对应、原签名有效、仍属于原账户和原序号；改费用不影响随后
48	// 打包采用的费用，改到期轮次不影响有效性；篡改也不会随正常保存落盘。
49	func TestTxQueryResultIsIndependentCopy(t *testing.T) {
50		keys := genKeys(t, 4)
51		n, dir := newTestNode(t, keys, 10)
52		txA := NewTransaction(keys[0].priv, 1, []byte("alpha"), 3, 100)
53		txB := NewTransaction(keys[1].priv, 1, []byte("beta"), 7, 100)
54		if _, err := n.Submit(txA); err != nil {
55			t.Fatal(err)
56		}
57		if _, err := n.Submit(txB); err != nil {
58			t.Fatal(err)
59		}
60		idA, idB := txA.ID(), txB.ID()
61	
62		// 调用方取得按标识查询的结果并尽力改写。
63		info, err := n.Tx(idA)
64		if err != nil {
65			t.Fatal(err)
66		}
67		if info.Status != StatusQueued {
68			t.Fatalf("setup: status = %s, want %s", info.Status, StatusQueued)
69		}
70		tamperQueryTx(info.Tx)
71		info.ID = "tampered-id"
72		info.Status = StatusConfirmed
73	
74		// 节点再次按原标识查询，仍是提交时的完整交易。
75		got, err := n.Tx(idA)
76		if err != nil {
77			t.Fatal(err)
78		}
79		if got.Status != StatusQueued {
80			t.Fatalf("status after tamper = %s, want %s", got.Status, StatusQueued)
81		}
82		assertTxMatches(t, got.Tx, txA)
83	
84		// 交易仍属于原账户和原序号。
85		acct := n.Account(keys[0].pub)
86		if acct.ConfirmedSequence != 0 || len(acct.Pending) != 1 || acct.Gap != 0 {
87			t.Fatalf("account after Tx-result tamper wrong: %+v", acct)
88		}
89		assertTxMatches(t, acct.Pending[0].Tx, txA)
90		if acct.Pending[0].ID != idA || acct.Pending[0].Note != "waiting-pack" {
91			t.Fatalf("account pending entry wrong: %+v", acct.Pending[0])
92		}
93	
94		// 调用方改写账户查询结果中的交易：费用调低、序号改大、内容改写。
95		acct.Pending[0].Tx.Fee = 0
96		acct.Pending[0].Tx.Sequence = 50
97		acct.Pending[0].Tx.Content = []byte("hijacked")
98		acct.Pending[0].Tx.Signature[0] ^= 0xff
99		acct.ConfirmedSequence = 5
100	
101		// 两种查询路径互相不受对方结果的影响。
102		got2, err := n.Tx(idA)
103		if err != nil {
104			t.Fatal(err)
105		}
106		assertTxMatches(t, got2.Tx, txA)
107		acct2 := n.Account(keys[0].pub)
108		if acct2.ConfirmedSequence != 0 || len(acct2.Pending) != 1 {
109			t.Fatalf("account after Account-result tamper wrong: %+v", acct2)
110		}
111		assertTxMatches(t, acct2.Pending[0].Tx, txA)
112	
113		// 打包采用的费用不受篡改影响：txB（费用 7）仍排在 txA（费用 3）之前，
114		// 即使调用方曾把结果中 txA 的费用改成 1003。
115		p, err := n.Propose()
116		if err != nil {
117			t.Fatal(err)
118		}
119		want := []string{idB, idA}
120		if fmt.Sprint(p.TxIDs) != fmt.Sprint(want) {
121			t.Fatalf("proposal order = %v, want %v (caller fee edits must not leak)", p.TxIDs, want)
122		}
123	
124		// 到期轮次被改为当前轮次不影响有效性：结束本轮后交易不失效，回到排队。
125		if _, err := n.EndRound(); err != nil {
126			t.Fatal(err)
127		}
128		after, err := n.Tx(idA)
129		if err != nil {
130			t.Fatal(err)
131		}
132		if after.Status != StatusQueued {
133			t.Fatalf("status after EndRound = %s, want %s (caller expiry edits must not leak)", after.Status, StatusQueued)
134		}
135		assertTxMatches(t, after.Tx, txA)
136	
137		// 合法提交触发一次正常保存后重开，节点中仍是原交易。
138		txC := NewTransaction(keys[2].priv, 1, []byte("c"), 1, 100)
139		if _, err := n.Submit(txC); err != nil {
140			t.Fatal(err)
141		}
142		reopened, err := Open(dir)
143		if err != nil {
144			t.Fatal(err)
145		}
146		stored, err := reopened.Tx(idA)
147		if err != nil {
148			t.Fatal(err)
149		}
150		assertTxMatches(t, stored.Tx, txA)
151		storedAcct := reopened.Account(keys[0].pub)
152		if storedAcct.ConfirmedSequence != 0 || len(storedAcct.Pending) != 1 {
153			t.Fatalf("account after reopen wrong: %+v", storedAcct)
154		}
155		assertTxMatches(t, storedAcct.Pending[0].Tx, txA)
156	}
157	
158	// 同一笔交易可以先后取得多份结果，也可以同时出现在交易查询和账户查询中：
159	// 编辑其中一份，其他已取得的结果保留各自取得时的内容，新取得的结果保持节点原值。
160	func TestMultipleTxQueryResultsIndependent(t *testing.T) {
161		keys := genKeys(t, 4)
162		n, _ := newTestNode(t, keys, 10)
163		tx := NewTransaction(keys[0].priv, 1, []byte("shared"), 4, 100)
164		if _, err := n.Submit(tx); err != nil {
165			t.Fatal(err)
166		}
167		id := tx.ID()
168	
169		first, err := n.Tx(id)
170		if err != nil {
171			t.Fatal(err)
172		}
173		second, err := n.Tx(id)
174		if err != nil {
175			t.Fatal(err)
176		}
177		acct := n.Account(keys[0].pub)
178		if len(acct.Pending) != 1 {
179			t.Fatalf("setup: pending = %d, want 1", len(acct.Pending))
180		}
181		fromAcct := acct.Pending[0]
182	
183		// 编辑先取得的一份，其余已取得的结果保持取得时的内容。
184		tamperQueryTx(first.Tx)
185		assertTxMatches(t, second.Tx, tx)
186		assertTxMatches(t, fromAcct.Tx, tx)
187	
188		// 再编辑账户查询取得的一份，另一份与新查询仍保持原值。
189		tamperQueryTx(fromAcct.Tx)
190		assertTxMatches(t, second.Tx, tx)
191		fresh, err := n.Tx(id)
192		if err != nil {
193			t.Fatal(err)
194		}
195		assertTxMatches(t, fresh.Tx, tx)
196		freshAcct := n.Account(keys[0].pub)
197		if len(freshAcct.Pending) != 1 {
198			t.Fatalf("pending after tamper = %d, want 1", len(freshAcct.Pending))
199		}
200		assertTxMatches(t, freshAcct.Pending[0].Tx, tx)
201	}
202	
203	// 账户列表里有多笔交易时，改写其中一笔不影响相邻交易的内容、所属账户或序号；
204	// 账户的已确认序号、待处理次序和缺口说明也不随调用方编辑而变化。
205	func TestAccountPendingNeighborsUnaffected(t *testing.T) {
206		keys := genKeys(t, 4)
207		n, _ := newTestNode(t, keys, 10)
208		tx1 := NewTransaction(keys[0].priv, 1, []byte("one"), 1, 100)
209		tx2 := NewTransaction(keys[0].priv, 2, []byte("two"), 2, 100)
210		tx4 := NewTransaction(keys[0].priv, 4, []byte("four"), 4, 100) // 序号 3 留缺口
211		for _, tx := range []*Transaction{tx1, tx2, tx4} {
212			if _, err := n.Submit(tx); err != nil {
213				t.Fatal(err)
214			}
215		}
216	
217		acct := n.Account(keys[0].pub)
218		if acct.ConfirmedSequence != 0 || acct.Gap != 3 || len(acct.Pending) != 3 {
219			t.Fatalf("setup: account = %+v", acct)
220		}
221		wantIDs := []string{tx1.ID(), tx2.ID(), tx4.ID()}
222		var gotIDs []string
223		for _, p := range acct.Pending {
224			gotIDs = append(gotIDs, p.ID)
225		}
226		if fmt.Sprint(gotIDs) != fmt.Sprint(wantIDs) {
227			t.Fatalf("setup: pending order = %v, want %v", gotIDs, wantIDs)
228		}
229	
230		// 改写中间那笔的内容、发送者与序号。
231		mid := acct.Pending[1]
232		mid.Tx.Content = []byte("hijacked")
233		mid.Tx.Sender = append([]byte(nil), keys[1].pub...)
234		mid.Tx.Sequence = 7
235		mid.Tx.Signature[0] ^= 0xff
236		mid.ID = "tampered-id"
237	
238		// 相邻交易的内容、所属账户与序号不变，被改写的交易在节点中保持原值。
239		again := n.Account(keys[0].pub)
240		if again.ConfirmedSequence != 0 || again.Gap != 3 || len(again.Pending) != 3 {
241			t.Fatalf("account summary changed by caller edit: %+v", again)
242		}
243		wantTxs := []*Transaction{tx1, tx2, tx4}
244		for i, want := range wantTxs {
245			got := again.Pending[i]
246			if got.ID != wantIDs[i] {
247				t.Fatalf("pending[%d] id = %s, want %s", i, got.ID, wantIDs[i])
248			}
249			assertTxMatches(t, got.Tx, want)
250		}
251		// 按标识查询邻居与被改写交易，同样保持提交时的内容。
252		for i, want := range wantTxs {
253			info, err := n.Tx(wantIDs[i])
254			if err != nil {
255				t.Fatal(err)
256			}
257			assertTxMatches(t, info.Tx, want)
258		}
259		// 被改写交易没有“搬到”其他账户名下。
260		other := n.Account(keys[1].pub)
261		if other.ConfirmedSequence != 0 || len(other.Pending) != 0 || other.Gap != 0 {
262			t.Fatalf("neighbor account should be untouched: %+v", other)
263		}
264	}
265	
266	// 查询结果是取得时的快照：交易原本排队，调用方取得结果后节点产生提议，
267	// 新查询显示该交易已进入提议、账户说明变为等待投票，而先前保存的结果仍显示
268	// 取得时的排队状态和内容；编辑旧结果不改变当前提议的交易标识与顺序。
269	func TestQueryResultIsSnapshotAcrossProposal(t *testing.T) {
270		keys := genKeys(t, 4)
271		n, _ := newTestNode(t, keys, 10)
272		tx := NewTransaction(keys[0].priv, 1, []byte("snap"), 5, 100)
273		if _, err := n.Submit(tx); err != nil {
274			t.Fatal(err)
275		}
276		id := tx.ID()
277	
278		// 提议产生前取得查询结果。
279		beforeTx, err := n.Tx(id)
280		if err != nil {
281			t.Fatal(err)
282		}
283		if beforeTx.Status != StatusQueued {
284			t.Fatalf("setup: status = %s, want %s", beforeTx.Status, StatusQueued)
285		}
286		beforeAcct := n.Account(keys[0].pub)
287		if len(beforeAcct.Pending) != 1 || beforeAcct.Pending[0].Note != "waiting-pack" {
288			t.Fatalf("setup: account pending = %+v", beforeAcct.Pending)
289		}
290	
291		// 节点产生提议。
292		p, err := n.Propose()
293		if err != nil {
294			t.Fatal(err)
295		}
296		if fmt.Sprint(p.TxIDs) != fmt.Sprint([]string{id}) {
297			t.Fatalf("setup: proposal = %v, want [%s]", p.TxIDs, id)
298		}
299	
300		// 新查询显示交易已进入提议、账户说明变为等待投票。
301		afterTx, err := n.Tx(id)
302		if err != nil {
303			t.Fatal(err)
304		}
305		if afterTx.Status != StatusProposed {
306			t.Fatalf("status after propose = %s, want %s", afterTx.Status, StatusProposed)
307		}
308		afterAcct := n.Account(keys[0].pub)
309		if len(afterAcct.Pending) != 1 || afterAcct.Pending[0].Note != "waiting-vote" {
310			t.Fatalf("account note after propose = %+v, want waiting-vote", afterAcct.Pending)
311		}
312	
313		// 先前保存的结果仍显示取得时的排队状态和内容。
314		if beforeTx.Status != StatusQueued {
315			t.Fatalf("saved result status changed to %s, want %s", beforeTx.Status, StatusQueued)
316		}
317		assertTxMatches(t, beforeTx.Tx, tx)
318		if beforeAcct.Pending[0].Note != "waiting-pack" {
319			t.Fatalf("saved account note changed to %s, want waiting-pack", beforeAcct.Pending[0].Note)
320		}
321		assertTxMatches(t, beforeAcct.Pending[0].Tx, tx)
322	
323		// 编辑旧结果，当前提议的交易标识与顺序保持原样。
324		tamperQueryTx(beforeTx.Tx)
325		beforeTx.ID = "tampered-id"
326		tamperQueryTx(beforeAcct.Pending[0].Tx)
327		again, ok := n.Proposal()
328		if !ok {
329			t.Fatal("proposal should exist")
330		}
331		if fmt.Sprint(again.TxIDs) != fmt.Sprint([]string{id}) || again.BlockID != p.BlockID {
332			t.Fatalf("proposal changed by caller edit: %+v", again)
333		}
334		rc, err := n.Candidates(1)
335		if err != nil {
336			t.Fatal(err)
337		}
338		if len(rc.Candidates) != 1 || fmt.Sprint(rc.Candidates[0].TxIDs) != fmt.Sprint([]string{id}) {
339			t.Fatalf("candidate history changed by caller edit: %+v", rc.Candidates)
340		}
341	}
342	
343	// 内容为空也是合法交易：查询保留它的标识、签名和其他字段；
344	// 调用方给这份结果填入内容，不会把原交易变成另一笔交易。
345	func TestEmptyContentTxQueryResultStaysIntact(t *testing.T) {
346		keys := genKeys(t, 4)
347		n, _ := newTestNode(t, keys, 10)
348		tx := NewTransaction(keys[0].priv, 1, nil, 2, 100)
349		if _, err := n.Submit(tx); err != nil {
350			t.Fatal(err)
351		}
352		id := tx.ID()
353	
354		info, err := n.Tx(id)
355		if err != nil {
356			t.Fatal(err)
357		}
358		if info.ID != id || len(info.Tx.Content) != 0 {
359			t.Fatalf("empty-content tx query wrong: %+v", info)
360		}
361		assertTxMatches(t, info.Tx, tx)
362	
363		// 调用方给手中的结果填入内容。
364		info.Tx.Content = []byte("filled-by-caller")
365		filledID := info.Tx.ID()
366		if filledID == id {
367			t.Fatal("setup: filled content should change the computed id")
368		}
369		acct := n.Account(keys[0].pub)
370		if len(acct.Pending) != 1 {
371			t.Fatalf("setup: pending = %d, want 1", len(acct.Pending))
372		}
373		acct.Pending[0].Tx.Content = []byte("filled-via-account")
374	
375		// 原交易仍是那笔空内容交易：标识、签名与各字段不变。
376		got, err := n.Tx(id)
377		if err != nil {
378			t.Fatal(err)
379		}
380		if got.ID != id || len(got.Tx.Content) != 0 {
381			t.Fatalf("original tx changed by caller fill: %+v", got)
382		}
383		assertTxMatches(t, got.Tx, tx)
384		again := n.Account(keys[0].pub)
385		if len(again.Pending) != 1 || again.Pending[0].ID != id || len(again.Pending[0].Tx.Content) != 0 {
386			t.Fatalf("account pending changed by caller fill: %+v", again.Pending)
387		}
388		// 填入内容后算出的标识并没有成为节点中的另一笔交易。
389		if _, err := n.Tx(filledID); reason(err) != ReasonUnknownTx {
390			t.Fatalf("filled id got %v, want %s", err, ReasonUnknownTx)
391		}
392	}
