383	// EndRound：所有候选落选不留块，交易回池；查询明确显示未确认结束。
384	func TestEndRoundAllCandidatesLost(t *testing.T) {
385		keys := genKeys(t, 4)
386		n, _ := newTestNode(t, keys, 10)
387		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
388		n.Submit(a1)
389		local, _ := n.Propose()
390		alt, err := n.RegisterCandidate(1, []string{}) // 空块竞争候选
391		if err != nil {
392			t.Fatal(err)
393		}
394		n.Vote(keys[0].pub, 1, local.BlockID)
395		n.Vote(keys[1].pub, 1, alt.BlockID)
396	
397		r, err := n.EndRound()
398		if err != nil || r != 2 {
399			t.Fatalf("EndRound = %d, %v", r, err)
400		}
401		rc, _ := n.Candidates(1)
402		if !rc.Ended || !rc.UnconfirmedEnd {
403			t.Fatalf("ended round should be marked unconfirmed-end: %+v", rc)
404		}
405		for _, c := range rc.Candidates {
406			if c.Result != CandidateLost {
407				t.Fatalf("candidate %s result = %s, want lost", c.BlockID, c.Result)
408			}
409		}
410		// 旧票不影响新轮次：同一名验证者可在新轮次重新选择。
411		p2, _ := n.Propose()
412		if res, err := n.Vote(keys[0].pub, 2, p2.BlockID); err != nil || !res.Counted {
413			t.Fatalf("vote in new round: %+v %v", res, err)
414		}
415		if info, _ := n.Tx(a1.ID()); info.Status != StatusProposed {
416			t.Fatalf("a1 should be proposed again in round 2: %s", info.Status)
417		}
418	}
419	
420	// 候选查询排序、未投票名单与防御性拷贝。
421	func TestCandidatesQuery(t *testing.T) {
422		keys := genKeys(t, 4)
423		n, _ := newTestNode(t, keys, 10)
424		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
425		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
426		n.Submit(a1)
427		n.Submit(b1)
428		local, _ := n.Propose() // 打包顺序：b1 先、a1 后。
429		altID := registerMust(t, n, 1, []string{a1.ID(), b1.ID()})
430		emptyID := registerMust(t, n, 1, []string{})
431		if altID == local.BlockID {
432			t.Fatal("test setup: alt candidate must differ from local")
433		}
434	
435		// 未知轮次。
436		if _, err := n.Candidates(0); reason(err) != ReasonUnknownRound {
437			t.Fatalf("round 0 got %v, want %s", err, ReasonUnknownRound)
438		}
439		if _, err := n.Candidates(9); reason(err) != ReasonUnknownRound {
440			t.Fatalf("future round got %v, want %s", err, ReasonUnknownRound)
441		}
442	
443		n.Vote(keys[3].pub, 1, altID)
444		n.Vote(keys[0].pub, 1, local.BlockID)
445		rc, err := n.Candidates(1)
446		if err != nil {
447			t.Fatal(err)
448		}
449		// 候选按区块标识排序。
450		var ids []string
451		for _, c := range rc.Candidates {
452			ids = append(ids, c.BlockID)
453		}
454		sorted := append([]string{}, ids...)
455		sortStrings(sorted)
456		if fmt.Sprint(ids) != fmt.Sprint(sorted) {
457			t.Fatalf("candidates not sorted: %v", ids)
458		}
459		// 投票者按公钥排序。
460		for _, c := range rc.Candidates {
461			prev := ""
462			for _, v := range c.Voters {
463				h := fmt.Sprintf("%x", v)
464				if h < prev {
465					t.Fatal("voters not sorted by public key")
466				}
467				prev = h
468			}
469		}
470		// 未投票验证者：keys[1]、keys[2]，按公钥排序。
471		if len(rc.Unvoted) != 2 {
472			t.Fatalf("unvoted = %d, want 2", len(rc.Unvoted))
473		}
474		unvotedSet := map[string]bool{}
475		for _, v := range rc.Unvoted {
476			unvotedSet[fmt.Sprintf("%x", v)] = true
477		}
478		if !unvotedSet[fmt.Sprintf("%x", keys[1].pub)] || !unvotedSet[fmt.Sprintf("%x", keys[2].pub)] {
479			t.Fatalf("unvoted set wrong: %x", rc.Unvoted)
480		}
481		if fmt.Sprintf("%x", rc.Unvoted[0]) > fmt.Sprintf("%x", rc.Unvoted[1]) {
482			t.Fatal("unvoted validators must be sorted by public key")
483		}
484		// 未决出时结果为 pending。
485		for _, c := range rc.Candidates {
486			if c.Result != CandidatePending {
487				t.Fatalf("candidate %s result = %s, want pending", c.BlockID, c.Result)
488			}
489		}
490	
491		// 防御性拷贝：调用方修改返回结果不影响节点。
492		var altView *CandidateView
493		for i := range rc.Candidates {
494			if rc.Candidates[i].BlockID == altID {
495				altView = &rc.Candidates[i]
496			}
497		}
498		if altView == nil || len(altView.TxIDs) == 0 || len(altView.Voters) == 0 {
499			t.Fatalf("alt view missing data: %+v", altView)
500		}
501		originalFirstTx := altView.TxIDs[0]
502		altView.TxIDs[0] = "tampered"
503		altView.Voters[0][0] ^= 0xff
504		rc.Unvoted[0][0] ^= 0xff
505		rc2, _ := n.Candidates(1)
506		var alt2 *CandidateView
507		for i := range rc2.Candidates {
508			if rc2.Candidates[i].BlockID == altID {
509				alt2 = &rc2.Candidates[i]
510			}
511		}
512		if alt2.TxIDs[0] != originalFirstTx {
513			t.Fatal("mutation of candidate tx ids leaked into node state")
514		}
515		// 原节点内的投票仍有效（重复投票不计数即说明身份比对未被破坏）。
516		if res, err := n.Vote(keys[3].pub, 1, altID); err != nil || res.Counted {
517			t.Fatalf("node state corrupted by caller mutation: %+v %v", res, err)
518		}
519		_ = emptyID
520	}
521	
522	// 停止后恢复候选、每人已投的选择与历史结果。
523	func TestCandidatesPersistence(t *testing.T) {
524		keys := genKeys(t, 4)
525		dir := t.TempDir()
526		vals := make([][]byte, len(keys))
527		for i, k := range keys {
528			vals[i] = k.pub
529		}
530		n, err := New(dir, Config{Seed: []byte("persist-cand"), Validators: vals, MaxTxsPerBlock: 5})
531		if err != nil {
532			t.Fatal(err)
533		}
534		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
535		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
536		n.Submit(a1)
537		n.Submit(b1)
538		local, _ := n.Propose() // 打包顺序：b1 先、a1 后。
539		altID := registerMust(t, n, 1, []string{a1.ID(), b1.ID()})
540		if altID == local.BlockID {
541			t.Fatal("test setup: alt candidate must differ from local")
542		}
543		n.Vote(keys[0].pub, 1, local.BlockID)
544		n.Vote(keys[1].pub, 1, altID)
545		n.Vote(keys[2].pub, 1, altID)
546	
547		n2, err := Open(dir)
548		if err != nil {
549			t.Fatal(err)
550		}
551		rc, err := n2.Candidates(1)
552		if err != nil {
553			t.Fatal(err)
554		}
555		if len(rc.Candidates) != 2 {
556			t.Fatalf("candidates restored = %d, want 2", len(rc.Candidates))
557		}
558		byID := map[string]CandidateView{}
559		for _, c := range rc.Candidates {
560			byID[c.BlockID] = c
561		}
562		if c := byID[local.BlockID]; !c.Local || len(c.Voters) != 1 {
563			t.Fatalf("local candidate restored wrong: %+v", c)
564		}
565		if c := byID[altID]; c.Local || len(c.Voters) != 2 {
566			t.Fatalf("alt candidate restored wrong: %+v", c)
567		}
568		if p, ok := n2.Proposal(); !ok || p.BlockID != local.BlockID {
569			t.Fatalf("local proposal not restored: %+v", p)
570		}
571		// 每人的选择恢复：重复不计数、改投拒绝。
572		if res, _ := n2.Vote(keys[1].pub, 1, altID); res.Counted {
573			t.Fatal("restored vote should dedup")
574		}
575		if _, err := n2.Vote(keys[1].pub, 1, local.BlockID); reason(err) != ReasonAlreadyVoted {
576			t.Fatalf("switch after reopen got %v, want %s", err, ReasonAlreadyVoted)
577		}
578		// 再补一票，竞争候选确认。
579		res, err := n2.Vote(keys[3].pub, 1, altID)
580		if err != nil || !res.Confirmed {
581			t.Fatalf("alt should confirm after reopen: %+v %v", res, err)
582		}
583		// 历史结果保留，新轮无候选记录。
584		rc, _ = n2.Candidates(1)
585		for _, c := range rc.Candidates {
586			want := CandidateWon
587			if c.BlockID != altID {
588				want = CandidateLost
589			}
590			if c.Result != want {
591				t.Fatalf("history result = %s, want %s", c.Result, want)
592			}
593		}
594		if _, err := n2.Candidates(2); reason(err) != ReasonUnknownRound {
595			t.Fatalf("fresh round should have no records, got %v", err)
596		}
597	}
598	
599	// 版本 1 的旧状态目录仍可打开：未决提议与票数作为本地候选恢复，
600	// 过去没有保存的候选详情明确显示无记录，确认块不变。
601	func TestOpenV1State(t *testing.T) {
602		keys := genKeys(t, 4)
603		dir := t.TempDir()
604		vals := make([][]byte, len(keys))
605		for i, k := range keys {
606			vals[i] = k.pub
607		}
608		n, err := New(dir, Config{Seed: []byte("v1-seed"), Validators: vals, MaxTxsPerBlock: 5})
609		if err != nil {
