617		// 把当前状态改写为版本 1 的文件形态：仅 Proposal 字段，没有 Rounds。
618		st := n.st.clone()
619		rs := st.Rounds[1]
620		local := rs.Candidates[rs.LocalBlockID]
621		st.Version = 1
622		st.Rounds = nil
623		st.Proposal = &proposalState{
624			Round:   rs.Round,
625			TxIDs:   append([]string{}, local.TxIDs...),
626			BlockID: local.BlockID,
627			Votes:   append([]string{}, local.Votes...),
628		}
629		writeRawState(t, dir, st)
