725	// 登记失败、投票失败、结束轮次失败时保存错误必须保留操作前状态。
726	func TestCandidateOpsAtomicity(t *testing.T) {
727		keys := genKeys(t, 4)
728		n, dir := newTestNode(t, keys, 10)
729		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
730		n.Submit(a1)
731		local, _ := n.Propose()
732	
733		n.injectSaveErr = errors.New("disk full (simulated)")
734		_, err := n.RegisterCandidate(1, []string{})
735		if err == nil {
736			t.Fatal("register must fail when save fails")
737		}
738		rc, _ := n.Candidates(1)
739		if len(rc.Candidates) != 1 {
740			t.Fatalf("failed register changed state: %d candidates", len(rc.Candidates))
741		}
742		// 投票触发确认时保存失败：轮次不得前进。
743		_, err = n.Vote(keys[0].pub, 1, local.BlockID)
744		if err == nil {
745			t.Fatal("vote must fail when save fails")
746		}
747		if n.CurrentRound() != 1 || n.Height() != 0 {
748			t.Fatalf("failed vote changed state: round=%d height=%d", n.CurrentRound(), n.Height())
749		}
750		// 结束轮次保存失败：轮次不得前进。
751		_, err = n.EndRound()
752		if err == nil {
753			t.Fatal("end round must fail when save fails")
754		}
755		if n.CurrentRound() != 1 {
756			t.Fatalf("failed EndRound changed round: %d", n.CurrentRound())
757		}
758		n.injectSaveErr = nil
759	
760		// 磁盘文件仍是操作前状态。
761		reopened, err := Open(dir)
762		if err != nil {
763			t.Fatal(err)
764		}
765		rc, _ = reopened.Candidates(1)
766		if len(rc.Candidates) != 1 {
767			t.Fatalf("disk state changed despite failed saves: %d candidates", len(rc.Candidates))
768		}
769		if res, err := reopened.Vote(keys[0].pub, 1, local.BlockID); err != nil || !res.Counted {
770			t.Fatalf("vote after reopen: %+v %v", res, err)
771		}
772	}
773	
774	func registerMust(t *testing.T, n *Node, round uint64, ids []string) string {
775		t.Helper()
776		r, err := n.RegisterCandidate(round, ids)
777		if err != nil {
778			t.Fatalf("register %v: %v", ids, err)
779		}
780		return r.BlockID
781	}
782	
783	func confirmCandidate(t *testing.T, n *Node, keys []testKey, blockID string) {
784		t.Helper()
785		round := n.CurrentRound()
786		count := len(keys)*2/3 + 1
787		for i := 0; i < count; i++ {
788			res, err := n.Vote(keys[i].pub, round, blockID)
789			if err != nil {
790				t.Fatalf("vote %d: %v", i, err)
791			}
792			if i == count-1 && !res.Confirmed {
793				t.Fatalf("vote %d should confirm %s", i+1, blockID)
794			}
795		}
796	}
797	
798	func sortStrings(s []string) {
799		for i := 1; i < len(s); i++ {
800			for j := i; j > 0 && s[j-1] > s[j]; j-- {
801				s[j-1], s[j] = s[j], s[j-1]
802			}
803		}
804	}
805	
806	func writeRawState(t *testing.T, dir string, st *state) {
807		t.Helper()
808		raw, err := json.MarshalIndent(st, "", "  ")
809		if err != nil {
810			t.Fatal(err)
811		}
812		if err := os.WriteFile(filepath.Join(dir, stateFileName), raw, 0o644); err != nil {
813			t.Fatal(err)
814		}
815	}
